  const uint64_t da = mk_desc((uint32_t)__cvta_generic_to_shared(As), lbo, sbo, swz);
  const uint64_t db = mk_desc((uint32_t)__cvta_generic_to_shared(Bs), lbo, sbo, swz);
  asm volatile(\"wgmma.fence.sync.aligned;\\\\n\");
  for (int ks = 0; ks < steps; ++ks) wg64(acc, da + ks * 2, db + ks * 2);
  asm volatile(\"wgmma.commit_group.sync.aligned;\\\\n\");
  asm volatile(\"wgmma.wait_group.sync.aligned 0;\\\\n\");
  const int warp = threadIdx.x >> 5;
