    C[r0 * 64 + c] = acc[j * 4 + 0];
    C[r0 * 64 + c + 1] = acc[j * 4 + 1];
    C[(r0 + 8) * 64 + c] = acc[j * 4 + 2];
    C[(r0 + 8) * 64 + c + 1] = acc[j * 4 + 3];
  }
