      s[nt][0] = exp2_approx(fmaf(s[nt][0], kScaleL2e, -mScaled0));
      s[nt][1] = exp2_approx(fmaf(s[nt][1], kScaleL2e, -mScaled0));
      s[nt][2] = exp2_approx(fmaf(s[nt][2], kScaleL2e, -mScaled1));
      s[nt][3] = exp2_approx(fmaf(s[nt][3], kScaleL2e, -mScaled1));
      sum0 += s[nt][0] + s[nt][1];
      sum1 += s[nt][2] + s[nt][3];
    }
