// A read that lands in A contributes 8*2"'^(c/8) per element (multiple of 64 per
// 16B chunk); a read landing in B contributes 1.0; elsewhere 0.5. The residue
// of C mod 64 therefore counts the stray reads, and C/64 is the chunk bitmask.
#include <cuda_bf16.h>
#include <cuda_runtime.h>
#include <torch/extension.h>

namespace {

__device__ __forceinline__ int smem_off(int r, int c, int mode) {
  switch (mode) {
    case 0: return r * 128 + c;
    case 1: return 8 * (r & 7) + (c & 7) + 64 * (r >> 3) + 512 * (c >> 3);
    case 2: return (r & 7) + 8 * (c & 7) + 64 * (r >> 3) + 512 * (c >> 3);
    default: return 8 * (r & 7) + (c & 7) + 1024 * (r >> 3) + 64 * (c >> 3);
  }
}

__device__ __forceinline__ uint32_t smem_u32(const void* p) {
