}

__device__ __forceinline__ uint64_t mk_desc(uint32_t addr, int lbo, int sbo, int swz) {
  return (uint64_t)((addr >> 4) & 0x3FFFu) | ((uint64_t)((lbo >> 4) & 0x3FFFu) << 16) |
         ((uint64_t)((sbo >> 4) & 0x3FFFu) << 32) | ((uint64_t)swz << 62);
