// Causal grouped-query attention prefill, raw CUDA + tensor-core (mma.sync) kernel.
//
// Layout of one CTA (kBc = 64 keys):
//
//   grid.x = mTiles * HQ, work item = (m, head);  m runs longest-last so that
//   the triangular work is scheduled biggest-first.
//
//   smem:  Q[64x136]   K[2 x 64x136]   V[2 x 64x136]   P[64x72]
//          \_____  ____/  \__ double buffered via cp.async __/
//                \________________________________/
//                          padded rows: 136*2 = 272 B = 68 banks
//
//   warp w owns query rows [w*16, w*16+16):  S = QK^T (8x m16n8k16 / k-step)
//   then online softmax in the log2 domain, P stored to smem as bf16 and
//   consumed as the A operand of the PV mma against V (ldmatrix.trans).
#include <c10/cuda/CUDAGuard.h>
#include <c10/cuda/CUDAStream.h>
#include <cuda_bf16.h>
#include <cuda_runtime.h>
#include <torch/extension.h>

#include <cstdint>

namespace {

// ---------------------------------------------------------------------------
// Problem constants
// ---------------------------------------------------------------------------
constexpr int kDim = 128;                 // head dimension, fixed
constexpr float kSqrtDim = 11.313708498984761f;
constexpr float kLog2e = 1.4426950408889634f;
constexpr float kScaleL2e = kLog2e / kSqrtDim;   // score scale folded into log2
constexpr float kMasked = -1.0e30f;              // stands in for -inf

// ---------------------------------------------------------------------------
// CTA tile: 64 query rows x 64 keys, 4 warps of 16 query rows
// ---------------------------------------------------------------------------
constexpr int kThreads = 128;
constexpr int kWarps = 4;
constexpr int kBr = 64;
constexpr int kBc = 64;
constexpr int kRowsPerWarp = kBr / kWarps;
constexpr int kPad = 8;                   // elements, breaks ldmatrix bank conflicts
constexpr int kQS = kDim + kPad;
constexpr int kKS = kDim + kPad;
constexpr int kVS = kDim + kPad;
constexpr int kChunks = kDim / 8;         // 16 B chunks per row
constexpr int kTileLoads = kBc * kChunks / kThreads;
constexpr int kQLoads = kBr * kChunks / kThreads;

constexpr size_t kSmemElems = (size_t)kBr * kQS + 4 * (size_t)kBc * kKS;
constexpr int kSmemBytes = (int)(kSmemElems * sizeof(__nv_bfloat16));

// ---------------------------------------------------------------------------
// PTX helpers
// ---------------------------------------------------------------------------
__device__ __forceinline__ uint32_t smem_u32(const void* p) {
  return static_cast<uint32_t>(__cvta_generic_to_shared(p));
}

__device__ __forceinline__ void cp_async16(void* dst, const void* src) {
  asm volatile("cp.async.cg.shared.global [%0], [%1], 16;\n" ::"r"(smem_u32(dst)), "l"(src));
}
__device__ __forceinline__ void cp_commit() { asm volatile("cp.async.commit_group;\n"); }
template <int kPending>
__device__ __forceinline__ void cp_wait() {
  asm volatile("cp.async.wait_group %0;\n" ::"n"(kPending));
}

