      cp_commit();
      cp_wait<1>();
    } else {
      cp_wait<0>();
    }
    __syncthreads();

    // ---- S = Q K^T -------------------------------------------------------
    float s[8][4];
#pragma unroll
    for (int nt = 0; nt < 8; ++nt)
#pragma unroll
      for (int i = 0; i < 4; ++i) s[nt][i] = 0.f;

#pragma unroll
    for (int ks = 0; ks < 8; ++ks) {
#pragma unroll
      for (int np = 0; np < 4; ++np) {
        uint32_t bFrag[4];
        ldsm4(smem_u32(&kTile[(np * 16 + k_row(lane)) * kKS + ks * 16 + k_col(lane)]), bFrag);
